      "title": "MMSR",
      "link": "https://arxiv.org/abs/2403.17372v1",
      "contributions": [
        "Studies joint adaptation of content encoders and sequential recommendation modules and their fusion."
      ],
      "limitations": [
        "Uses pretrained content encoders, which are unavailable under this task’s constraints.",
        "Does not validate the proposed randomly initialized text encoder."
      ]
    },
    {
      "title": "Deep Unordered Composition Rivals Syntactic Methods for Text Classification",
      "link": "https://aclanthology.org/P15-1162/",
      "contributions": [
        "Establishes deep averaging networks as useful unordered text-classification baselines.",
        "Motivates retaining mean pooling as a controlled low-complexity ablation."
      ],
      "limitations": [
        "Does not establish recommendation or physical-compatibility understanding.",
        "Context-independent mean pooling cannot distinguish token sequences with identical multisets."
      ]
    },
    {
      "title": "What You Can Cram into a Single Vector: Probing Sentence Embeddings for Linguistic Properties",
      "link": "https://aclanthology.org/P18-1198/",
      "contributions": [
        "Provides probing tasks for word content and word-order information.",
        "Motivates measuring representation sensitivity separately from downstream ranking."
      ],
      "limitations": [
        "Connector-direction and dimension-assignment probes are proposed product-specific adaptations.",
        "Probe sensitivity alone does not establish correct compatibility judgments."
      ]
    },
    {
      "title": "TensorFlow sampled_softmax_loss documentation",
      "link": "https://www.tensorflow.org/api_docs/python/tf/nn/sampled_softmax_loss",
      "contributions": [
        "Documents sampled-softmax behavior and accidental target-hit handling."
      ],
      "limitations": [
        "Excluding every known training positive requires additional user-specific handling.",
        "Its expected-count correction convention differs from the deterministic-positive importance estimator."
      ]
    },
    {
      "title": "Candidate Sampling",
      "link": "https://www.tensorflow.org/extras/candidate_sampling.pdf",
      "contributions": [
        "Explains candidate-sampling objectives and expected-count semantics.",
        "Supports specifying proposal probabilities and duplicate handling explicitly."
      ],
      "limitations": [
        "Does not establish that a particular correction or sampler improves this benchmark.",
        "Replacement draws and unique-set inclusion probabilities require different corrections."
      ]
    },
    {
      "title": "On the Bias of Sampled Softmax",
      "link": "https://arxiv.org/abs/1712.00527",
      "contributions": [
        "Analyzes bias associated with sampled-softmax estimation.",
        "Supports distinguishing sampled discrimination from catalog-normalizer approximation."
      ],
      "limitations": [
        "Does not identify an optimal negative count or objective for these four categories.",
        "Importance weighting does not generally eliminate finite-sample loss or gradient bias."
      ]
    },
